TLM.f("Sancti/09-15",{"officium":"Septem Dolorum Beatæ Mariæ Virginis","rule":["ex C11;","Gloria","Sequentia","Credo","Prefatio=Maria=Transfixióne;"],"ruleInherited":["Gloria","Credo","Prefatio=Maria=Festivitate","Gloria","Suffr=Spiritu;Ecclesiæ,Papa;;","Prefatio=Maria=veneratione;"],"fallback":"Commune/C11","from":{"GradualeP":"Commune/C11","Tractus":"Commune/C11"},"sections":{"Introitus":[{"k":"ref","la":"Joann 19:25"},{"k":"text","la":"Stabant juxta Crucem Jesu Mater ejus, et soror Matris ejus, María Cléophæ, et Salóme et María Magdaléne."},{"k":"ref","la":"Joann 19:26-27"},{"k":"text","la":"Múlier, ecce fílius tuus: dixit Jesus; ad discípulum autem: Ecce Mater tua."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Stabant juxta Crucem Jesu Mater ejus, et soror Matris ejus, María Cléophæ, et Salóme et María Magdaléne."}],"Oratio":[{"k":"text","la":"Deus, in cuius passióne, secúndum Simeónis prophetíam, dulcíssimam ánimam gloriósae Vírginis et Matris Maríae dolóris gládius pertransívit: concéde propítius; ut, qui dolóres eius venerándo recólimus, passiónis tuae efféctum felícem consequámur:"},{"k":"macro","name":"Qui vivis"}],"Lectio":[{"k":"text","la":"Léctio libri Judith"},{"k":"ref","la":"Judith 13:22; 13:23-25"},{"k":"text","la":"Benedíxit te Dóminus in virtúte sua, quia per te ad níhilum redégit inimícos nostros. Benedícta es tu, fília, a Dómino, Deo excélso, præ ómnibus muliéribus super terram. Benedíctus Dóminus, qui creávit cœlum et terram: quia hódie nomen tuum ita magnificávit, ut non recédat laus tua de ore hóminum, qui mémores fúerint virtútis Dómini in ætérnum, pro quibus non pepercísti ánimæ tuæ propter angústias et tribulatiónem géneris tui, sed subvenísti ruínæ ante conspéctum Dei nostri."}],"Graduale":[{"k":"text","la":"Dolorósa et lacrimábilis es, Virgo María, stans juxta Crucem Dómini Jesu, Fílii tui, Redemptóris."},{"k":"text","la":"Virgo Dei Génetrix, quem totus non capit orbis, hoc crucis fert supplícium, auctor vitæ factus homo.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"text","la":"Stabat sancta María, cœli Regína et mundi Dómina, juxta Crucem Dómini nostri Jesu Christi dolorósa.","mark":"V"}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Num 17:8"},{"k":"text","la":"Virga Jesse flóruit: Virgo Deum et hóminem génuit: pacem Deus réddidit, in se reconcílians ima summis"},{"k":"ref","la":"Luke 1:28"},{"k":"text","la":"Ave, María, grátia plena; Dóminus tecum: benedícta tu in muliéribus. Allelúja."}],"Tractus":[{"k":"text","la":"Benedícta et venerábilis es, Virgo María: quæ sine tactu pudóris invénia es Mater Salvatóris."},{"k":"text","la":"Virgo, Dei Génetrix, quem totus non capit orbis, in tua se clausit víscera factus homo.","mark":"V"},{"k":"text","la":"Gaude, María Virgo, cunctas hǽreses sola interemísti."},{"k":"text","la":"Quæ Gabriélis Archángeli dictis credidísti.","mark":"V"},{"k":"text","la":"Dum Virgo Deum et hóminem genuísti: et post partum, Virgo, invioláta permansísti.","mark":"V"},{"k":"text","la":"Dei Génetrix, intercéde pro nobis.","mark":"V"}],"Sequentia":[{"k":"text","la":"Stabat Mater dolorósa"},{"k":"text","la":"Juxta Crucem lacrimósa,"},{"k":"text","la":"Dum pendébat Fílius."},{"k":"sep"},{"k":"text","la":"Cujus ánimam geméntem,"},{"k":"text","la":"Contristátam et doléntem"},{"k":"text","la":"Pertransívit gládius."},{"k":"sep"},{"k":"text","la":"O quam tristis et afflícta"},{"k":"text","la":"Fuit illa benedícta"},{"k":"text","la":"Mater Unigéniti!"},{"k":"sep"},{"k":"text","la":"Quæ mærébat et dolébat,"},{"k":"text","la":"Pia Mater, dum vidébat"},{"k":"text","la":"Nati pœnas íncliti."},{"k":"sep"},{"k":"text","la":"Quis est homo, qui non fleret,"},{"k":"text","la":"Matrem Christi si vidéret"},{"k":"text","la":"In tanto supplício?"},{"k":"sep"},{"k":"text","la":"Quis non posset contristári,"},{"k":"text","la":"Christi Matrem contemplári"},{"k":"text","la":"Doléntem cum Fílio?"},{"k":"sep"},{"k":"text","la":"Pro peccátis suæ gentis"},{"k":"text","la":"Vidit Jesum in torméntis"},{"k":"text","la":"Et flagéllis súbditum."},{"k":"sep"},{"k":"text","la":"Vidit suum dulcem"},{"k":"text","la":"Natum Moriéndo desolátum,"},{"k":"text","la":"Dum emísit spíritum."},{"k":"sep"},{"k":"text","la":"Eja, Mater, fons amóris,"},{"k":"text","la":"Me sentíre vim dolóris"},{"k":"text","la":"Fac, ut tecum lúgeam."},{"k":"sep"},{"k":"text","la":"Fac, ut árdeat cor meum"},{"k":"text","la":"In amándo Christum Deum,"},{"k":"text","la":"Ut sibi compláceam."},{"k":"sep"},{"k":"text","la":"Sancta Mater, istud agas,"},{"k":"text","la":"Crucifixi fige plagas"},{"k":"text","la":"Cordi meo válida."},{"k":"sep"},{"k":"text","la":"Tui Nati vulneráti,"},{"k":"text","la":"Tam dignáti pro me pati,"},{"k":"text","la":"Pœnas mecum dívide."},{"k":"sep"},{"k":"text","la":"Fac me tecum pie flere,"},{"k":"text","la":"Crucifíxo condolére,"},{"k":"text","la":"Donec ego víxero."},{"k":"sep"},{"k":"text","la":"Juxta Crucem tecum stare"},{"k":"text","la":"Et me tibi sociáre"},{"k":"text","la":"In planctu desídero."},{"k":"sep"},{"k":"text","la":"Virgo vírginum præclára."},{"k":"text","la":"Mihi jam non sis amára:"},{"k":"text","la":"Fac me tecum plángere."},{"k":"sep"},{"k":"text","la":"Fac, ut portem Christi mortem,"},{"k":"text","la":"Passiónis fac consórtem"},{"k":"text","la":"Et plagas recólere."},{"k":"sep"},{"k":"text","la":"Fac me plagis vulnerári,"},{"k":"text","la":"Fac me Cruce inebriári"},{"k":"text","la":"Et cruóre Fílii."},{"k":"sep"},{"k":"text","la":"Flammis ne urar succénsus,"},{"k":"text","la":"Per te, Virgo, sim defénsus"},{"k":"text","la":"In die judícii."},{"k":"sep"},{"k":"text","la":"Christe, cum sit hinc exíre."},{"k":"text","la":"Da per Matrem me veníre"},{"k":"text","la":"Ad palmam victóriæ."},{"k":"sep"},{"k":"text","la":"Quando corpus moriétur,"},{"k":"text","la":"Fac, ut ánimæ donétur"},{"k":"text","la":"Paradísi glória."},{"k":"text","la":"Amen. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joann 19:25-27"},{"k":"text","la":"In illo témpore: Stabant juxta Crucem Jesu Mater ejus, et soror Matris ejus, María Cléophæ, et María Magdaléne. Cum vidísset ergo Jesus Matrem, et discípulum stantem, quem diligébat, dicit Matri suæ: Múlier, ecce fílius tuus. Deinde dicit discípulo: Ecce Mater tua. Et ex illa hora accépit eam discípulus in sua."}],"Offertorium":[{"k":"ref","la":"Ierem 18, 20"},{"k":"text","la":"Recordáre, Virgo Mater Dei, dum stéteris in conspéctu Dómini, ut loquáris pro nobis bona, et ut avértat indignatiónem suam a nobis."}],"Secreta":[{"k":"text","la":"Offérimus tibi preces et hóstias, Dómine Jesu Christe, humiliter supplicántes: ut, qui Transfixiónem dulcíssimi spíritus beátæ Maríæ, Matris tuæ, précibus recensémus; suo suorúmque sub Cruce Sanctórum consórtium multiplicáto piíssimo intervéntu, méritis mortis tuæ, méritum cum beátis habeámus:"},{"k":"macro","name":"Qui vivis"}],"Communio":[{"k":"text","la":"Felíces sensus beátæ Maríæ Vírginis, qui sine morte meruérunt martýrii palmam sub Cruce Dómini."}],"Postcommunio":[{"k":"text","la":"Sacrifícia, quæ súmpsimus, Dómine Jesu Christe, Transfixiónem Matris tuæ et Vírginis devóte celebrántes: nobis ímpetrent apud cleméntiam tuam omnis boni salutáris efféctum:"},{"k":"macro","name":"Qui vivis"}]},"hr":{"c9e9f5552f64b036":{"t":"Iv 19, 25, Iv 19, 26-27\n(Iv 19, 25) Uz Križ je Isusov stajala njegova Majka i sestra njegove Majke Marija Kleofina i Saloma i Marija Magdalena. (Io 19, 26-27) Isus reče: Ženo evo ti sina; zatim reče učeniku: Evo ti majke.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Iv 19, 25) Uz Križ je Isusov stajala njegova Majka i sestra njegove Majke Marija Kleofina i Saloma i Marija Magdalena.","kn":"TJlaz (Iv. 19. .25-27). Stajahu kod križa Isusova mati njegova i sestra matere njegove Marija Kleofkia I Saioma i Marija Magdalena. Ženo, eto ti sina, reče Isus; a (Po tom reče učeniku; Eto ti matere! Slava Ocu. Stajahu.","knRef":"Kniewald 1942, str. 706–707 (snimka 354) (OCR)"},"8da64354b6faaca3":{"t":"<i>Pomolimo se</i>.\nBože, za vrijeme tvoje muke mač je boli prostrijelio po Šimunovu proročanstvu presvetu dušu slavne Djevice i majke Marije: daj milostivo, da mi koji s poštovanjem slavimo njezine žalosti postignemo sretni učinak tvoje muke:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Za Tvoje je muke, Bože, po Simeonbvu proročanstvu] bolni mač prošao preslatkom dušom slavne Djevice i Majke Marije: dopusti blago- Sedam žalosti Bi. Dj. Marije 15. IX. Štivo, da mi, koji se s počitanjem sjećamo njezinih bolii (zagovorom slavnih zasluga] i molitava sv svetih, koji vjerno stoje uz križ)i sretni dostignemo učinak Tvoje muke, koji živiš i kraljujes . . .","knRef":"Kniewald 1942, str. 706–707 (snimka 354) (OCR)"},"b2df66fb929738f1":{"t":"Jud 13, 22 i 23-25\nČitanje knjige Judite. Gospodin te obdario svojom snagom, i po tebi je uništio naše neprijatelje. Ti si, kćeri, blagoslovljena od Gospodina, Svevišnjega Boga, više nego sve druge žene na zemlji. Blagoslovljen Gospodin, koji je stvorio nebo i zemlju: on je danas tako uzveličao tvoje ime, da ti pohvale neće prestati pjevati ljudi, koji će se vjekovima sjećati Božje moći. Za njih. zbog tjeskobe i nevolje svojega naroda, ti nisi štedjela sebe nego si spriječila propast pred našim Bogom.","kn":"Čitanje knjige Juditine (13, 22-25). Gospt^n je blagoslovio svojom jakošću, jer je po tebi uništio naše neprijatelje. Ti si. kćeri, od Boga Svevišnjega blagoslovljena vrše od svih žena na zemlji. Blagoslovljen Gospodin, koji je stvorio nebo i zemlju, koji je danas tako uzvelicao tvoje ime da ne će prestati tvoja hvala od ljudi, koji će se uvijek sjećati moći Gospodnje. Jer mjesi štedila sebe. kad si vidjela boli i muke svoga naroda, nego si spriječila propast pre-d našim o-","knRef":"Kniewald 1942, str. 706–707 (snimka 354) (OCR)"},"a46e045d8824e015":{"t":"Bila si puna boli i suza. Djevo Marijo, dok si stala uz Križ Otkupitelja, Gospodina Isusa, Sina svoga. O Djevo Bogorodice, smrtnu kaznu na Križu podnosi onaj koga cijeli svijet ne može obuhvatiti, početnik života koji je postao čovjek.\n\n<i>Aleluja</i>, <i>aleluja</i>.\nStala je sveta Marija, Kraljica neba i Gospodarica svijeta, puna boli uz Križ Gospodina našega Isusa Krista.","kn":"Puna si boli i suza, djevice Mar rijo, stojeći do križa Gospod,ina Isusa, Sina svoga, Spasitelja. Djevice, Bogorodice, ovu križnu muku podnaša začetnik života postavši čovjek, koga čitav svijet ne može da obuhvati.\n\n(Aleluja, aleluja. Stajaše sveta Marija, kraljica neba i gospodarica svijeta, do križa Gospodina našega Isusa, puna boM.)","knRef":"Kniewald 1942, str. 706–707 (snimka 354) (OCR)"},"08be0820212dd9b8":{"t":"Stala plačuć' tužna mati,/Gledala je kako pati/Sin joj na križ uzdignut. <i>\n</i>\nDušom njenom razboljenom,/Rastuženom, ražaljenom,/Prolazio mač je ljut. <i>\n</i>\nO koliko ucviljena/Bješe ona uzvišena/Majka Sina jedinog! <i>\n</i>\nBol bolova sve to ljući/Blaga Mati gledajući/Muke slavnog Čeda svog. <i>\n</i>\nKoji čovjek ne bi plak'o/Majku Božju videć' tako/U tjeskobi tolikoj! <i>\n</i>\nTko protužit' neće s Čistom,/Kada vidi gdje za Kristom/Razdire se srce njoj ? <i>\n</i>\nZarad grijeha svoga puka/Gleda njega usred muka/I gdje bičem bijen bi. <i>\n</i>\nGleda svoga milog Sina,/Ostavljenog sred gorčina,/Gdje se s dušom podijeli. <i>\n</i>\nVrelo milja, slatka Mati,/Bol mi gorku osjećati/Daj, da s tobom procvilim. <i>\n</i>\nNeka ljubav srca moga/Gori sveđ za Krista Boga,/Da mu u svem omilim. <i>\n</i>\nRane drage, Majko sveta/Spasa za me razapeta/Tisni usred srca mog! <i>\n</i>\nNeka dođu i na mene/Patnje za me podnesene/Sina tvoga ranjenog. <i>\n</i>\nDaj mi s tobom suze livat',/Raspetoga oplakivat',/Dok na svijetu budem ja. <i>\n</i>\nU tom društvu uz križ stati,/S tobom jade jadovati/Želja mi je jedna. <i>\n</i>\nKruno djeva, Djevo divna,/Budi meni milostivna,/Daj mi s tobom dijelit plač. <i>\n</i>\nDaj mi nosit' po sve dane/Isusovu smrt i rane/Osjećati muka mač; <i>\n</i>\nNeka rane izrane me,/Neka svega opoje me/Sina tvoga križ i krv. <i>\n</i>\nTi na sudu za me zbori,/Djevo sveta, da ne mori/Pakleni me vječni crv. <i>\n</i>\nKada dođu smrtni časi,/Kriste Bože, nek me spasi/Majke tvoje zagovor. <i>\n</i>\nKad mi zemlja tijelo primi,/Dušu onda uzmi ti mi,/U nebeskim blažen dvor. <i>\n</i>\n<i>amen</i>.\n<i>Aleluja</i>."},"0768acb23b8db282":{"t":"Iv 19, 25-27\nSlijedi sveto Evanđelje po Luki. U ono vrijeme: Stajale su kod križa Isusova njegova Majka i sestra Majke njegove Marija Kleofina i Marija Magdalena. Kada dakle vidje Isus Majku i učenika, koga ljubljaše gdje stoji, reče svojoj Majci: Ženo, evo ti sina. Zatim reče učeniku: Evo ti majke. I od onoga časa uze je učenik k sebi.","kn":"t Slijedi sveto Evanđelje po Ivanu (19, 25-27). U ono vrijeme stajale su uz Isusov križ njegova majka i sestra njegove majke Marija, Kleofina i Marija Magdalena. Kad je Isus viidio majku i uz nju učenika, kojega je ljubio, reče svojoj majci: Ženo, evo ti sina! Zatim reče učeniku: Evo ti majke! I od onoga časa uze je učenik k sebi.","knRef":"Kniewald 1942, str. 710–711 (snimka 356) (OCR)"},"9bf12f4c210d513f":{"t":"Jr 18, 20\nSpomeni se, Djevice, Majko Božja dok stojiš pred licem Gospodnjim da nas zagovaraš, neka otkloni srdžbu svoju od nas.","kn":"Spomeni se djevice, , majfco: Božja, stojeći pred licem Goiapodnjim, da nam budeš zagovornicom,, da otkloni, od nas srdžbu svoju.","knRef":"Kniewald 1942, str. 710–711 (snimka 356) (OCR)"},"15d27ce9c9f0fb0d":{"t":"Prinosimo ti molitve i darove, Gospodine Isuse Kriste, ponizno moleći, da mi koji u molitvama razmišljamo o žalostima presvete duše blažene Marije Majke tvoje po milom zagovoru njezinu i njezinih svetih pratilaca pod križem zavrijedimo sudjelovati u nagradi svetih po zaslugama tvoje smrti:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"f45068e9ae040523":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože: i da te <i>o žalostima</i> blažene Marije vazda Djevice hvalimo, blagoslivljamo i slavimo. Ona je osjenjena Duhom Svetim začela jedinorođenoga Sina tvoga i sačuvavši slavu djevičanstva prosula svijetom vječno svjetlo Isusa Krista Gospodina našega. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, da uvijek i, svagdje Tebi, Gospodine sveti. Oče svemogući, vječni Bože, zahvaljujemo i da Te hvalimo, slavimo i uzvisujemo o (Pohodu, Prikazanju, Bezgrješnom Začeću, Navještenju, Uznesenju. Rođenju, svetkovini) blažene Marije, vazda Djevice, koja je po Duhu Svetom začela jedinorođenoga Tvoga Sina i zadržavši slavu djevičanstva dala svijetu vječno svijetlo, Isuisa Krista, Gospodina našega, po kome anđeli hvale Tvoje veličanstvo, klanjaju Ti se gospodstva, podlažu Ti se vlasti, slave Te nebesa i nebeske sile s blaženim Serafinima kličući u zajedničkoj^ radosti. A mi Te molimo, da nam zapovjediš s njima sjediniti naše glasove smjerno ispovijedajući:","knRef":"Kniewald 1942, str. 22–23 (snimka 12) (OCR)"},"a108e2f74c777084":{"t":"O sretnih li osjetila blažene Djevice Marije, što su bez smrti zaslužila mučeničku palmu pod Križem Gospodnjim.","kn":"O sretna sjetila blažene Marije Djevice, koja su bez smrti zaslužila mučeničku paomu pod križem Gospodnjim.","knRef":"Kniewald 1942, str. 710–711 (snimka 356) (OCR)"},"f24543bf9f3bd47e":{"t":"<i>Pomolimo se</i>.\nŽrtve koje smo primili, Gospodine Isuse Kriste, slaveći pobožno žalosti tvoje Majke i Djevice, neka nam izmole kod tvoje dobrote svako spasonosno dobro:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Žrtve, koje posvetismo, Gospodine Isukrste, pobožno svetkujući probođenje Majke Tvoje 1 Djevice: neka nam izraole kod Tvoje blagosti učinak svakog spasonosnog dobra,; koji živiš i kraljuješ . . , Očistila nas, . Gospodine, svetotajstva, sto smo ih primili i . zagovorom blaženog Nikodema, mučenik Tvoga, .odriješila nas od svih. mana, po G. n.","knRef":"Kniewald 1942, str. 710–711 (snimka 356) (OCR)"}},"variants":{"paschal":{"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Num 17:8"},{"k":"text","la":"Virga Jesse flóruit: Virgo Deum et hóminem génuit: pacem Deus réddidit, in se reconcílians ima summis."},{"k":"ref","la":"Luc 1:28"},{"k":"text","la":"Ave, María, grátia plena; Dóminus tecum: benedícta tu in muliéribus. Allelúja."}],"Tractus":[{"k":"text","la":"Gaude, María Virgo, cunctas hǽreses sola interemísti."},{"k":"text","la":"Quæ Gabriélis Archángeli dictis credidísti.","mark":"V"},{"k":"text","la":"Dum Virgo Deum et hóminem genuísti: et post partum, Virgo, invioláta permansísti.","mark":"V"},{"k":"text","la":"Dei Génetrix, intercéde pro nobis.","mark":"V"}]}}});
